import test from 'node:test';
import assert from 'node:assert/strict';
import {discount} from '../src/cart.mjs';
test('zero percent preserves total', () => assert.equal(discount(100,0),100));
test('25 percent reduces the total', () => assert.equal(discount(200,25),150));
test('100 percent reduces the total to zero', () => assert.equal(discount(100,100),0));
